package com.theone.series;
import android.content.Intent;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.concurrent.atomic.AtomicBoolean;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class SeriesNavigationTest {
 @Test public void sourcesRemainSeparatedAndSeriesOnly()throws Exception{MediaRepository r=new MediaRepository(InstrumentationRegistry.getInstrumentation().getTargetContext());assertTrue(r.headersForUri("http://cqqwnnig.bulidns.com/series/test").isEmpty());assertEquals(1,r.headersForUri("https://rubenvanaggelen.com/the-one-remote-api/cinema.php?action=stream").size());try{r.load("movies");fail("Movie catalog must be rejected");}catch(java.io.IOException expected){}}
 @Test public void phoneSearchSeasonsEpisodesAndPlaybackWork()throws Exception{UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());Intent i=new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);i.putExtra("series_test_mode",true);try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(i)){
  assertTrue(device.wait(Until.hasObject(By.textContains("THE ONE SERIES")),10000));assertNull(device.findObject(By.text("Films")));assertNull(device.findObject(By.text("XXX")));device.findObject(By.clazz("android.widget.EditText")).setText("testserie 3");device.waitForIdle();assertTrue(device.wait(Until.hasObject(By.text("EN - Series testserie 3")),5000));device.findObject(By.text("EN - Series testserie 3")).click();assertTrue(device.wait(Until.hasObject(By.text("Seizoenen en afleveringen")),5000));device.findObject(By.text("Seizoenen en afleveringen")).click();assertTrue(device.wait(Until.hasObject(By.text("Seizoen 1")),5000));device.findObject(By.text("Seizoen 1")).click();assertTrue(device.wait(Until.hasObject(By.textContains("S01E01")),5000));device.findObject(By.textContains("S01E01")).click();assertTrue(device.wait(Until.hasObject(By.text("▶ Kijk")),5000));device.findObject(By.text("▶ Kijk")).click();AtomicBoolean playing=new AtomicBoolean(false);for(int n=0;n<40&&!playing.get();n++){scenario.onActivity(a->playing.set(a.isPlaybackReadyForTest()));Thread.sleep(250);}assertTrue("Episode renders a real video frame",playing.get());device.pressBack();device.waitForIdle();scenario.onActivity(a->a.findViewById(1006).performClick());assertTrue(device.wait(Until.hasObject(By.text("Seizoen 2")),5000));device.findObject(By.text("Seizoen 2")).click();assertTrue(device.wait(Until.hasObject(By.textContains("S02E01")),5000));scenario.onActivity(a->a.findViewById(1001).performClick());device.waitForIdle();assertNull(device.findObject(By.textContains("S02E01")));
 }}
}
